import pandas as pd
trips = tables['trips']
t2 = trips[trips.fish_date_season==2]

def bucket_ypa(df, lo, hi, cls):
    d = df[(df.fish_date_doy>=lo)&(df.fish_date_doy<hi)&(df.cls==cls)]
    return d.yt.sum(), d.anglers.sum(), (d.yt.sum()/d.anglers.sum() if d.anglers.sum()>0 else None), len(d)

rows=[]
for lo,hi in [(152,182)]:
    for cls in ['three_quarter','overnight','day_1_5','hd_am','hd_pm']:
        rows.append((lo,hi,cls)+bucket_ypa(t2,lo,hi,cls))
result = pd.DataFrame(rows, columns=['lo','hi','cls','yt','anglers','ypa','n'])
